func handler(req map[string]interface{}) map[string]interface{} {
	bodyStr, _ := req["body"].(string)
	var body map[string]interface{}
	json.Unmarshal([]byte(bodyStr), &body)

	action, _ := body["action"].(string)
	if action == "" {
		action = "uppercase"
	}

	input, _ := body["input"].(string)

	switch action {
	case "uppercase":
		return map[string]interface{}{"result": strings.ToUpper(input)}
	case "lowercase":
		return map[string]interface{}{"result": strings.ToLower(input)}
	case "reverse":
		runes := []rune(input)
		for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
			runes[i], runes[j] = runes[j], runes[i]
		}
		return map[string]interface{}{"result": string(runes)}
	case "word_count":
		words := strings.Fields(input)
		freq := make(map[string]int)
		for _, w := range words {
			freq[strings.ToLower(w)]++
		}
		return map[string]interface{}{"word_count": len(words), "unique": len(freq), "frequency": freq}
	case "base64_encode":
		return map[string]interface{}{"result": Base64Encode(input)}
	case "base64_decode":
		decoded, err := Base64Decode(input)
		if err != nil {
			return map[string]interface{}{"error": err.Error()}
		}
		return map[string]interface{}{"result": decoded}
	default:
		return map[string]interface{}{"error": "unknown action", "available": []string{"uppercase", "lowercase", "reverse", "word_count", "base64_encode", "base64_decode"}}
	}
}
